// ===========================================================================
// MOTOR DE ALARMAS  —  modelo de estados ISA-18.2
//
// ENTRADA (una de dos):
//   a) Estado de una maquina:
//        msg.topic   = 'M01'
//        msg.payload = { estado:'run', valores:{ Bandeja:true, ... } }
//   b) Reconocimiento desde la pantalla:
//        msg.topic   = 'ack'
//        msg.payload = { id:'M01.DISC.Bandeja' }   // o { todas:true }
//
// SALIDA 1 -> pantalla de alarmas (set completo, siempre)
// SALIDA 2 -> evento nuevo para persistir en SQLite (solo cuando hay cambio)
//
// ESTADOS:  NORM -> UNACK -> ACKED -> NORM
//                     \-> RTNUN (volvio a normal sin reconocer) -> NORM
// ===========================================================================

// --------------------------------------------------------------------------
// TABLA DE ALARMAS. Aqui se define QUE es una alarma. Nada mas es alarma.
//
//  tipo 'disc'  = discrepancia: el actuador esta en un estado y su final de
//                 carrera no responde en 'tmo' segundos.
//                 act=actuador  on=sensor esperado con act=true
//                               off=sensor esperado con act=false
//  tipo 'sens'  = fallo de sensor: los dos finales de carrera activos a la vez.
//                 Fisicamente imposible -> P1 siempre.
// --------------------------------------------------------------------------
const DEF = {
  M01: [
    { t:'disc', act:'Bandeja',     on:'BandejaAtras',   off:'BandejaFrente',  p:2, tmo:8,  d:'Bandeja no alcanza posicion' },
    { t:'disc', act:'BrazoEx',     on:'BrazoExtendido', off:'BrazoRecogido',  p:2, tmo:8,  d:'Brazo no alcanza posicion' },
    { t:'disc', act:'Piston',      on:'PistoAbajo',     off:'PistoArriba',    p:2, tmo:6,  d:'Piston inyector no responde' },
    { t:'disc', act:'AbrirMoldes', on:'PuertaAbierta',  off:'PuertaCerrada',  p:2, tmo:8,  d:'Puertas de molde no responden' },
    { t:'sens', a:'BandejaAtras',   b:'BandejaFrente',  p:1, d:'Fallo sensores de bandeja' },
    { t:'sens', a:'BrazoExtendido', b:'BrazoRecogido',  p:1, d:'Fallo sensores de brazo' },
    { t:'sens', a:'PistoAbajo',     b:'PistoArriba',    p:1, d:'Fallo sensores de piston' },
    { t:'sens', a:'PuertaAbierta',  b:'PuertaCerrada',  p:1, d:'Fallo sensores de puerta' }
  ],

  M02: [
    { t:'disc', act:'Alineacion', on:'Alineado', off:'SinAlinear', p:2, tmo:8, d:'Alineador no alcanza posicion' },
    { t:'disc', act:'GiroLavado', on:'Giro',     off:'SinGiro',    p:2, tmo:10,d:'Brazo de lavado no gira' },
    { t:'sens', a:'Alineado', b:'SinAlinear', p:1, d:'Fallo sensores de alineador' },
    { t:'sens', a:'Giro',     b:'SinGiro',    p:1, d:'Fallo sensores de giro' }
  ],

  M03: [
    { t:'disc', act:'ACT_LLT_AlineadorLlenado', on:'SE_LLT_AlineadorLlenadoExtendido', off:'SE_LLT_AlineadorLlenadoRetraido', p:2, tmo:8, d:'Alineador de llenado no responde' },
    { t:'disc', act:'ACT_LLT_BoquillaLlenado',  on:'SE_LLT_BoquillaAbajo',             off:'SE_LLT_BoquillaArriba',           p:2, tmo:8, d:'Boquillas no responden' },
    { t:'disc', act:'ACT_LLT_Remachadora',      on:'SE_LLT_RemachadoraAbajo',          off:'SE_LLT_RemachadoraArriba',        p:2, tmo:8, d:'Remachadora no responde' },
    { t:'sens', a:'SE_LLT_AlineadorLlenadoExtendido', b:'SE_LLT_AlineadorLlenadoRetraido', p:1, d:'Fallo sensores de alineador' },
    { t:'sens', a:'SE_LLT_BoquillaAbajo',             b:'SE_LLT_BoquillaArriba',           p:1, d:'Fallo sensores de boquilla' },
    { t:'sens', a:'SE_LLT_RemachadoraAbajo',          b:'SE_LLT_RemachadoraArriba',        p:1, d:'Fallo sensores de remachadora' }
  ],

  M04: [
    // Sin pares de finales de carrera -> sin alarmas de discrepancia ni de sensor.
    // (Cuando renombren el tag 'Pusher' se puede vigilar el cilindro de rechazo.)
  ],

  M05: [
    { t:'disc', act:'Freno',        on:'FrenoAbajo',              off:'FrenoArriba',           p:2, tmo:6, d:'Placa de freno no responde' },
    { t:'disc', act:'Barreras',     on:'BarreraRecogida',         off:'BarreraExtendida',      p:2, tmo:8, d:'Barreras guia no responden' },
    { t:'disc', act:'Caja',         on:'CajaArriba',              off:'CajaAbajo',             p:2, tmo:10,d:'Caja apiladora no responde' },
    { t:'disc', act:'Cuchillas',    on:'CuchillasCerradas',       off:'CuchillasAbiertas',     p:2, tmo:6, d:'Cuchillas no responden' },
    { t:'disc', act:'BrazoCelofan', on:'BrazoCelofanExtendido',   off:'BrazoCelofanRecogido',  p:2, tmo:8, d:'Brazo de celofan no responde' },
    { t:'sens', a:'FrenoAbajo',            b:'FrenoArriba',            p:1, d:'Fallo sensores de freno' },
    { t:'sens', a:'BarreraRecogida',       b:'BarreraExtendida',       p:1, d:'Fallo sensores de barreras' },
    { t:'sens', a:'CajaArriba',            b:'CajaAbajo',              p:1, d:'Fallo sensores de caja' },
    { t:'sens', a:'CuchillasCerradas',     b:'CuchillasAbiertas',      p:1, d:'Fallo sensores de cuchillas' },
    { t:'sens', a:'BrazoCelofanExtendido', b:'BrazoCelofanRecogido',   p:1, d:'Fallo sensores de brazo celofan' }
  ]
};

const NOMBRES = { M01:'Sopladora', M02:'Lavadora', M03:'Llenadora y Tapadora',
                  M04:'Inspeccionadora', M05:'Empaquetadora' };

const ahora = () => new Date().toLocaleTimeString('es-CO', { hour12:false });
const iso   = () => new Date().toISOString();

let A = flow.get('alarmas') || {};   // { id: {estado, prio, maq, desc, ts, tAct} }
const eventos = [];

function evento(id, ev) {
    const a = A[id];
    eventos.push({
        ts: iso(), maquina: a.maq, alarma_id: id,
        prioridad: a.prio, descripcion: a.desc, evento: ev
    });
}

// ---------------------------------------------------------------- RECONOCER
if (msg.topic === 'ack') {
    const p = msg.payload || {};
    for (const id of Object.keys(A)) {
        if (!p.todas && p.id !== id) continue;
        if (A[id].estado === 'UNACK') { A[id].estado = 'ACKED'; evento(id, 'RECONOCIDA'); }
        else if (A[id].estado === 'RTNUN') { evento(id, 'NORMAL'); delete A[id]; }
    }
}

// ------------------------------------------------------- EVALUAR UNA MAQUINA
if (msg.topic && DEF[msg.topic]) {
    const maq = msg.topic;
    const v   = (msg.payload && msg.payload.valores) || {};
    const t   = Date.now() / 1000;

    for (const def of DEF[maq]) {

        // --- construir id estable y evaluar la condicion ---
        let id, activa = false;

        if (def.t === 'sens') {
            id = `${maq}.SENS.${def.a}`;
            activa = v[def.a] === true && v[def.b] === true;   // ambos = imposible

        } else {                                              // discrepancia
            id = `${maq}.DISC.${def.act}`;
            const cmd = v[def.act];
            if (cmd === undefined) continue;
            const esperado = cmd ? def.on : def.off;
            const llego    = v[esperado] === true;

            // temporizador: cuenta desde que el actuador esta pidiendo y no llega
            const K = 'T_' + id;
            let t0 = flow.get(K);
            if (llego) { flow.set(K, null); }
            else {
                if (!t0) { flow.set(K, t); t0 = t; }
                activa = (t - t0) >= def.tmo;
            }
        }

        // --- maquina de estados ISA-18.2 ---
        const prev = A[id];

        if (activa && !prev) {
            A[id] = { estado:'UNACK', prio:def.p, maq, desc:def.d,
                      nombre:NOMBRES[maq], ts:ahora(), tAct:iso() };
            evento(id, 'ACTIVA');

        } else if (!activa && prev) {
            if (prev.estado === 'ACKED') { evento(id, 'NORMAL'); delete A[id]; }
            else if (prev.estado === 'UNACK') {
                // Volvio a normal SIN reconocer: no se borra, queda visible.
                // Es el fallo intermitente que de otro modo se perderia.
                prev.estado = 'RTNUN';
                evento(id, 'NORMAL_SIN_REC');
            }
        }
    }
}

flow.set('alarmas', A);

// ------------------------------------------------------------------- SALIDAS
const lista = Object.keys(A).map(id => Object.assign({ id }, A[id]))
    .sort((x, y) => (x.prio - y.prio) ||
                    ((x.estado === 'UNACK' ? 0 : 1) - (y.estado === 'UNACK' ? 0 : 1)) ||
                    (x.tAct < y.tAct ? 1 : -1));

const resumen = { P1:0, P2:0, P3:0, unack:0, total:lista.length };
lista.forEach(a => {
    resumen['P' + a.prio]++;
    if (a.estado === 'UNACK') resumen.unack++;
});

const salida1 = { topic:'alarmas', payload: { lista, resumen } };
const salida2 = eventos.length ? { payload: eventos } : null;

return [salida1, salida2];

// El motor entrega un array de eventos nuevos. SQLite inserta de a uno.
// El SQL vive DENTRO del nodo sqlite (modo prepared);
// aqui solo se mandan los parametros en msg.params.
return [ (msg.payload || []).map(e => ({
    params: {
        $ts:          e.ts,
        $maquina:     e.maquina,
        $alarma_id:   e.alarma_id,
        $prioridad:   e.prioridad,
        $descripcion: e.descripcion,
        $evento:      e.evento
    }
})) ];

// La pantalla manda dos cosas:
//   { accion:'ack',  id:'M01.DISC.Bandeja' }  o  { accion:'ack', todas:true }
//   { accion:'diario', limite:200 }
const p = msg.payload || {};

if (p.accion === 'ack') {
    return [{ topic:'ack', payload:{ id:p.id, todas:!!p.todas } }, null];
}

if (p.accion === 'diario') {
    const n = Math.min(Number(p.limite) || 200, 1000);
    return [null, {
        topic: `SELECT * FROM alarmas ORDER BY id DESC LIMIT ${n};`
    }];
}
return null;

msg.topic = 'diario';
msg.payload = { diario: msg.payload || [] };
return msg;

// ===========================================================================
// ACUMULADOR
//
// Entra el estado de una maquina (mismo msg que va al motor de alarmas):
//   msg.topic   = 'M01'
//   msg.payload = { estado:'run', valores:{ Salida:true, ... } }
//
// Hace dos cosas y NO escribe en disco (eso lo hace el volcado cada minuto):
//   1) Cuenta FLANCOS DE SUBIDA del sensor de salida -> produccion real.
//      El PLC no entrega contadores; se derivan aqui.
//   2) Acumula segundos en cada estado -> disponibilidad.
// ===========================================================================

// Sensor que marca una unidad producida en cada maquina.
// (!) M03 no tiene sensor de salida documentado: se usa el de entrada.
const SENSOR = {
    M01: { ok: 'Salida' },
    M02: { ok: 'ConteoBotellas' },
    M03: { ok: 'SE_LLT_ContadorEntrada' },
    M04: { ok: 'Salida', nok: 'BotDescartada' },
    M05: { ok: 'SalidaTunel' }
};

const maq = msg.topic;
if (!SENSOR[maq]) return null;

const p = msg.payload || {};
const v = p.valores || {};
const ahora = Date.now();

let A = flow.get('acum') || {};
if (!A[maq]) {
    A[maq] = { ok: 0, nok: 0, run: 0, pause: 0, stop: 0,
               estado: p.estado || 'stop', tUlt: ahora,
               prevOk: false, prevNok: false };
}
const a = A[maq];

// --- 1) Flancos de subida: false -> true cuenta una unidad ---
const sOk = v[SENSOR[maq].ok] === true;
if (sOk && !a.prevOk) a.ok++;
a.prevOk = sOk;

if (SENSOR[maq].nok) {
    const sNok = v[SENSOR[maq].nok] === true;
    if (sNok && !a.prevNok) a.nok++;
    a.prevNok = sNok;
}

// --- 2) Tiempo en cada estado ---
const dt = (ahora - a.tUlt) / 1000;
if (dt > 0 && dt < 60) {                      // se ignoran saltos raros
    if (a.estado === 'run')        a.run   += dt;
    else if (a.estado === 'pause') a.pause += dt;
    else                           a.stop  += dt;
}
a.tUlt = ahora;
if (p.estado) a.estado = p.estado;

flow.set('acum', A);
return null;                                   // no emite nada: solo acumula

// Cada minuto se escribe UNA fila por maquina y se reinician los acumuladores.
// Asi la base crece de forma acotada: 5 filas/min = 7.200 filas/dia.

const MAQ = ['M01', 'M02', 'M03', 'M04', 'M05'];
const A = flow.get('acum') || {};
const ts = new Date().toISOString();
const filas = [];

for (const m of MAQ) {
    const a = A[m];
    if (!a) continue;                       // esa maquina aun no reporta

    filas.push({
        ts, maquina: m, estado: a.estado,
        producidas:  a.ok,
        rechazadas:  a.nok,
        seg_run:   Math.round(a.run),
        seg_pause: Math.round(a.pause),
        seg_stop:  Math.round(a.stop)
    });

    // reinicio de la ventana (se conserva estado y flancos previos)
    a.ok = 0; a.nok = 0; a.run = 0; a.pause = 0; a.stop = 0;
}

flow.set('acum', A);
if (!filas.length) return null;
msg.payload = filas;
return msg;

// Una fila por maquina y por minuto.
// El SQL vive DENTRO del nodo sqlite (modo prepared).
return [ (msg.payload || []).map(f => ({
    params: {
        $ts:         f.ts,
        $maquina:    f.maquina,
        $estado:     f.estado,
        $producidas: f.producidas,
        $rechazadas: f.rechazadas,
        $run:        f.seg_run,
        $pause:      f.seg_pause,
        $stop:       f.seg_stop
    }
})) ];

// La pantalla pide:  { accion:'datos', horas:8 }
const p = msg.payload || {};
if (p.accion !== 'datos') return null;

const h = [1, 8, 24].includes(Number(p.horas)) ? Number(p.horas) : 8;
flow.set('rango_h', h);

// 1) Serie del historico
const q1 = `SELECT ts, maquina, estado, producidas, rechazadas, seg_run, seg_pause, seg_stop
            FROM historico
            WHERE datetime(ts) >= datetime('now', '-${h} hours')
            ORDER BY ts ASC;`;

// 2) Pareto de alarmas del mismo periodo (solo activaciones)
const q2 = `SELECT maquina, descripcion, prioridad, COUNT(*) AS veces
            FROM alarmas
            WHERE evento = 'ACTIVA' AND datetime(ts) >= datetime('now', '-${h} hours')
            GROUP BY maquina, descripcion, prioridad
            ORDER BY veces DESC
            LIMIT 12;`;

return [{ topic: q1 }, { topic: q2 }];

msg.topic = 'historico';
msg.payload = { filas: msg.payload || [], horas: flow.get('rango_h') || 8 };
return msg;

msg.topic = 'pareto';
msg.payload = { pareto: msg.payload || [] };
return msg;

// ===========================================================================
// DETECTOR DE CAMBIOS DE ESTADO
//
// Recibe el mismo msg que el motor de alarmas y el registrador de historicos.
// Solo emite cuando el estado de una maquina CAMBIA de verdad.
//
// Esto es clave: si escribieras una fila en cada tick tendrias 5 filas cada
// 200 ms (2,1 millones de filas al dia). Solo interesan las transiciones.
// ===========================================================================

const NOMBRES = {
    M01: 'Sopladora',  M02: 'Lavadora',        M03: 'Llenadora y Tapadora',
    M04: 'Inspeccionadora', M05: 'Empaquetadora'
};

const TXT = { run: 'EN MARCHA', pause: 'PAUSADA', stop: 'DETENIDA' };

const maq = msg.topic;
if (!NOMBRES[maq]) return null;

const nuevo = msg.payload && msg.payload.estado;
if (!nuevo) return null;

const K = 'ult_estado';
let E = flow.get(K) || {};
const anterior = E[maq];

if (anterior === nuevo) return null;      // sin cambio -> no se registra nada

E[maq] = nuevo;
flow.set(K, E);

const detalle = anterior
    ? `${NOMBRES[maq]}: ${TXT[anterior] || anterior} -> ${TXT[nuevo] || nuevo}`
    : `${NOMBRES[maq]}: estado inicial ${TXT[nuevo] || nuevo}`;

// El SQL vive DENTRO del nodo sqlite (modo prepared).
return {
    params: {
        $ts:      new Date().toISOString(),
        $tipo:    'ESTADO',
        $maquina: maq,
        $detalle: detalle
    }
};

// Evento de arranque del sistema.
msg.params = {
    $ts:      new Date().toISOString(),
    $tipo:    'SISTEMA',
    $maquina: null,
    $detalle: 'SCADA iniciado'
};
return msg;

// ===========================================================================
// CONSULTA UNIFICADA
//
// Une dos tablas en una sola linea de tiempo:
//   - eventos : cambios de estado, arranques del sistema
//   - alarmas : activaciones, reconocimientos, normalizaciones
//
// El UNION ALL permite ver la causalidad: la alarma entro, la maquina paro,
// el operario reconocio. Todo en orden cronologico real.
// ===========================================================================

const p = msg.payload || {};
if (p.accion !== 'buscar') return null;

const horas  = [1, 8, 24, 168].includes(Number(p.horas)) ? Number(p.horas) : 24;
const limite = Math.min(Number(p.limite) || 300, 5000);

// Filtros opcionales. Se escapan las comillas simples para evitar inyeccion.
const esc  = s => String(s).replace(/'/g, "''");
const maq  = p.maquina ? `AND maquina = '${esc(p.maquina)}'` : '';
const maqA = p.maquina ? `AND a.maquina = '${esc(p.maquina)}'` : '';

let fTipo = '';
if (p.tipo === 'ALARMA')   fTipo = 'alarma';
if (p.tipo === 'ESTADO')   fTipo = 'estado';
if (p.tipo === 'OPERADOR') fTipo = 'operador';
if (p.tipo === 'SISTEMA')  fTipo = 'sistema';

// --- rama 1: tabla eventos ---
const qEventos = `
  SELECT ts, tipo, maquina, detalle, NULL AS prioridad
  FROM eventos
  WHERE datetime(ts) >= datetime('now', '-${horas} hours') ${maq}
`;

// --- rama 2: tabla alarmas (los RECONOCIDA se marcan como OPERADOR) ---
const qAlarmas = `
  SELECT a.ts,
         CASE WHEN a.evento = 'RECONOCIDA' THEN 'OPERADOR' ELSE 'ALARMA' END AS tipo,
         a.maquina,
         a.descripcion || '  —  ' || a.evento AS detalle,
         a.prioridad
  FROM alarmas a
  WHERE datetime(a.ts) >= datetime('now', '-${horas} hours') ${maqA}
`;

let sql;
if (fTipo === 'estado' || fTipo === 'sistema') {
    sql = `${qEventos} AND tipo = '${fTipo.toUpperCase()}'`;
} else if (fTipo === 'alarma') {
    sql = `${qAlarmas} AND a.evento <> 'RECONOCIDA'`;
} else if (fTipo === 'operador') {
    sql = `${qAlarmas} AND a.evento = 'RECONOCIDA'`;
} else {
    sql = `${qEventos} UNION ALL ${qAlarmas}`;
}

msg.topic = `SELECT * FROM ( ${sql} ) ORDER BY ts DESC LIMIT ${limite};`;
return msg;

msg.topic = 'registros';
msg.payload = { registros: msg.payload || [] };
return msg;

// ===========================================================================
//  SIMULADOR INTEGRAL DE PLANTA  —  las 5 maquinas a la vez
//
//  Sustituye al PLC mientras el gemelo digital no este listo.
//  Cada maquina tiene ejes que se mueven de forma gradual, asi que los
//  finales de carrera se activan solo al llegar al tope: por eso el HMI
//  muestra "EN TRANSITO" de verdad y las alarmas de discrepancia
//  se disparan cuando algo no llega a tiempo.
//
//  SALIDA 1 -> 5 mensajes, uno por maquina (topic = M01..M05)
//              { estado, paso, valores:{...} }
//  SALIDA 2 -> resumen de estados para la vista general (1 vez por segundo)
//
//  COMANDOS (llegan de los inject, msg.topic = 'cmd'):
//     { maq:'M01', fallo:true }   traba los ejes -> alarma de discrepancia
//     { maq:'M02', modo:'stop' }  para la maquina
//     { limpiar:true }            quita fallos y todo vuelve a marcha
//     { demo:false }              desactiva las paradas aleatorias
//     { operario:'toggle' }       enciende / apaga el operario simulado
//     { reset:true }              reinicia el simulador desde cero
// ===========================================================================

const DT  = 0.2;                       // periodo del tick (s)
const IDS = ['M01', 'M02', 'M03', 'M04', 'M05'];

let S = flow.get('sim');

// ------------------------------------------------------------- COMANDOS
if (msg && msg.topic === 'cmd') {
    const p = msg.payload || {};
    if (p.reset) { S = null; flow.set('sim', null); }
    else if (S) {
        if (p.limpiar) { S.fallo = {}; S.tRec = {}; IDS.forEach(m => { S.modo[m] = 'run'; }); }
        if (p.maq && p.fallo !== undefined) { S.fallo[p.maq] = !!p.fallo; S.tRec[p.maq] = p.dur || 0; }
        if (p.maq && p.modo)                { S.modo[p.maq]  = p.modo;    S.tRec[p.maq] = p.dur || 0; }
        if (p.demo !== undefined) S.demo = !!p.demo;
        if (p.operario === 'toggle') {
            const off = !flow.get('op_off');
            flow.set('op_off', off);
            node.status({ fill: off ? 'grey' : 'green', shape: 'dot',
                          text: off ? 'operario simulado OFF' : 'operario simulado ON' });
        } else if (p.operario !== undefined) flow.set('op_off', !p.operario);
        flow.set('sim', S);
        return null;
    }
}

// ------------------------------------------------------------- ARRANQUE
if (!S) {
    const base = () => ({ paso: 1, t: 0, ok: 0, nok: 0, d: {}, pul: {} });
    S = {
        demo: true, tSeg: 0, fallo: {}, modo: {}, tRec: {},
        M01: Object.assign(base(), { ejes: { bandeja: 1, brazo: 0, piston: 0, puerta: 1 } }),
        M02: Object.assign(base(), { ejes: { alin: 0, giro: 0, freno: 0 }, pinzas: false }),
        M03: Object.assign(base(), { ejes: { alinL: 0, boq: 0, rem: 0, freno: 0 } }),
        M04: Object.assign(base(), { ejes: { push: 0 }, malo: false }),
        M05: Object.assign(base(), { ejes: { freno: 0, barrera: 0, caja: 0, cuch: 0, cel: 0, push: 0 },
                                     bot: 0, fila: 0 })
    };
    IDS.forEach(m => { S.modo[m] = 'run'; S.tRec[m] = 0; });
}
if (!S.tRec) S.tRec = {};

// --------------------------------------------------------------- UTILES
// Mueve un eje hacia su destino. Si la maquina tiene fallo inyectado el eje
// se vuelve 50 veces mas lento -> nunca llega -> alarma de discrepancia.
function mov(m, eje, destino, vel) {
    const e = S[m].ejes;
    const v = S.fallo[m] ? vel * 0.02 : vel;
    const paso = v * DT;
    if (Math.abs(e[eje] - destino) <= paso) e[eje] = destino;
    else e[eje] += (destino > e[eje] ? paso : -paso);
}

// Pulso: deja una deteccion en true durante n ticks. Los contadores de
// produccion cuentan flancos de subida, asi que necesitan pulsos limpios.
function pulso(m, k, n) { S[m].d[k] = true; S[m].pul[k] = n || 3; }

function tickPulsos(m) {
    const x = S[m];
    for (const k of Object.keys(x.pul)) {
        if (--x.pul[k] <= 0) { x.d[k] = false; delete x.pul[k]; }
    }
}

const activa = m => S.modo[m] === 'run';

// ================================================================ M01
function simM01() {
    const x = S.M01, E = x.ejes;
    const a = {
        BandaSopladora: activa('M01'),
        Bandeja: x.paso <= 2 || x.paso >= 7,
        Grib: x.paso >= 2 && x.paso <= 3 || x.paso === 7 && E.brazo > 0.02,
        BrazoEx: x.paso === 3 || x.paso === 6,
        AbrirMoldes: x.paso <= 3 || x.paso >= 6,
        Piston: x.paso === 5
    };
    if (S.modo.M01 === 'stop') { a.BandaSopladora = false; }

    mov('M01', 'bandeja', a.Bandeja ? 1 : 0, 2.5);
    mov('M01', 'brazo',   a.BrazoEx ? 1 : 0, 2.0);
    mov('M01', 'piston',  a.Piston  ? 1 : 0, 3.0);
    mov('M01', 'puerta',  a.AbrirMoldes ? 1 : 0, 2.0);

    const s = {
        BandejaAtras: E.bandeja >= 1, BandejaFrente: E.bandeja <= 0,
        BrazoRecogido: E.brazo <= 0, BrazoExtendido: E.brazo >= 1,
        PistoArriba: E.piston <= 0,  PistoAbajo: E.piston >= 1,
        PuertaAbierta: E.puerta >= 1, PuertaCerrada: E.puerta <= 0
    };

    if (activa('M01')) {
        x.t += DT;
        switch (x.paso) {
            case 1: if (s.BandejaAtras && s.PuertaAbierta) { x.paso = 2; x.t = 0; } break;
            case 2: if (x.t >= 0.6) { x.d.BotAtGrip = true; x.paso = 3; x.t = 0; } break;
            case 3: if (s.BrazoExtendido) { x.d.BotAtMolde = true; x.paso = 4; x.t = 0; } break;
            case 4: if (s.BrazoRecogido && s.PuertaCerrada) { x.d.BotAtMolde = false; x.paso = 5; x.t = 0; } break;
            case 5: if (s.PistoAbajo && x.t >= 2.0) { x.paso = 6; x.t = 0; } break;
            case 6: if (s.BrazoExtendido && s.PuertaAbierta) { x.paso = 7; x.t = 0; } break;
            case 7: if (s.BrazoRecogido) {
                        x.d.BotAtGrip = false; pulso('M01', 'Salida', 3);
                        x.ok++; x.paso = 1; x.t = 0;
                    } break;
        }
    }
    tickPulsos('M01');
    return Object.assign({}, a, s, x.d, { CNT_Salida: x.ok });
}

// ================================================================ M02
function simM02() {
    const x = S.M02, E = x.ejes;
    const a = {
        Banda: activa('M02') && x.paso <= 1,
        Detencion:   x.paso >= 2 && x.paso <= 5,
        Alineacion:  x.paso >= 3 && x.paso <= 5,
        CierrePinzas: x.paso >= 4 && x.paso <= 5,
        GiroLavado:  x.paso === 5
    };
    if (S.modo.M02 === 'stop') a.Banda = false;

    mov('M02', 'freno', a.Detencion  ? 1 : 0, 3.0);
    mov('M02', 'alin',  a.Alineacion ? 1 : 0, 2.2);
    mov('M02', 'giro',  a.GiroLavado ? 1 : 0, 1.4);

    const s = {
        ConDetecion: E.freno >= 1,
        SinAlinear:  E.alin <= 0, Alineado: E.alin >= 1,
        SinGiro:     E.giro <= 0, Giro:     E.giro >= 1
    };

    if (activa('M02')) {
        x.t += DT;
        switch (x.paso) {
            case 1: if (x.t >= 1.2) { pulso('M02', 'EntradaBotellas', 3); x.paso = 2; x.t = 0; } break;
            case 2: if (s.ConDetecion) { x.paso = 3; x.t = 0; } break;
            case 3: if (s.Alineado) { x.paso = 4; x.t = 0; } break;
            case 4: if (x.t >= 0.6) { x.paso = 5; x.t = 0; } break;
            case 5: if (s.Giro && x.t >= 2.5) { x.paso = 6; x.t = 0; } break;
            case 6: if (s.SinGiro && s.SinAlinear) {
                        pulso('M02', 'ConteoBotellas', 3);
                        x.ok++; x.paso = 1; x.t = 0;
                    } break;
        }
    }
    tickPulsos('M02');
    return Object.assign({}, a, s, x.d, { CNT_Lavadas: x.ok });
}

// ================================================================ M03
function simM03() {
    const x = S.M03, E = x.ejes;
    const a = {
        ACT_LLT_Banda: activa('M03') && x.paso <= 1,
        ACT_LLT_DetencionLlenado: x.paso >= 2 && x.paso <= 5,
        ACT_LLT_AlineadorLlenado: x.paso >= 3 && x.paso <= 5,
        ACT_LLT_BoquillaLlenado:  x.paso === 4,
        ACT_LLT_PosicionamientoTapado: x.paso === 7,
        ACT_LLT_Remachadora: x.paso === 9
    };
    if (S.modo.M03 === 'stop') a.ACT_LLT_Banda = false;

    mov('M03', 'freno', a.ACT_LLT_DetencionLlenado ? 1 : 0, 3.0);
    mov('M03', 'alinL', a.ACT_LLT_AlineadorLlenado ? 1 : 0, 2.2);
    mov('M03', 'boq',   a.ACT_LLT_BoquillaLlenado  ? 1 : 0, 2.0);
    mov('M03', 'rem',   a.ACT_LLT_Remachadora      ? 1 : 0, 2.4);

    const s = {
        SE_LLT_Sindetencion: E.freno <= 0,
        SE_LLT_AlineadorLlenadoRetraido:  E.alinL <= 0,
        SE_LLT_AlineadorLlenadoExtendido: E.alinL >= 1,
        SE_LLT_BoquillaArriba: E.boq <= 0, SE_LLT_BoquillaAbajo: E.boq >= 1,
        SE_LLT_RemachadoraArriba: E.rem <= 0, SE_LLT_RemachadoraAbajo: E.rem >= 1
    };

    if (activa('M03')) {
        x.t += DT;
        switch (x.paso) {
            case 1: if (x.t >= 1.0) { pulso('M03', 'SE_LLT_ContadorEntrada', 3); x.paso = 2; x.t = 0; } break;
            case 2: if (E.freno >= 1) { x.paso = 3; x.t = 0; } break;
            case 3: if (s.SE_LLT_AlineadorLlenadoExtendido) { x.paso = 4; x.t = 0; } break;
            case 4: if (s.SE_LLT_BoquillaAbajo && x.t >= 2.0) { x.paso = 5; x.t = 0; } break;
            case 5: if (s.SE_LLT_BoquillaArriba) { x.paso = 6; x.t = 0; } break;
            case 6: if (s.SE_LLT_AlineadorLlenadoRetraido && s.SE_LLT_Sindetencion) { x.paso = 7; x.t = 0; } break;
            case 7: if (x.t >= 1.2) { pulso('M03', 'SE_LLT_DeteccionBotellaTapado', 3); x.paso = 8; x.t = 0; } break;
            case 8: if (x.t >= 0.6) { pulso('M03', 'SE_LLT_AgregarTapa', 3); x.paso = 9; x.t = 0; } break;
            case 9: if (s.SE_LLT_RemachadoraAbajo && x.t >= 1.0) {
                        pulso('M03', 'SE_LLT_ParadaRemache', 3); x.paso = 10; x.t = 0;
                    } break;
            case 10: if (s.SE_LLT_RemachadoraArriba) { x.ok++; x.paso = 1; x.t = 0; } break;
        }
    }
    tickPulsos('M03');
    return Object.assign({}, a, s, x.d, { CNT_Llenadas: x.ok });
}

// ================================================================ M04
function simM04() {
    const x = S.M04, E = x.ejes;
    const a = {
        ConPrincipal: activa('M04'),
        Pusher: x.paso === 3
    };
    if (S.modo.M04 === 'stop') a.ConPrincipal = false;

    mov('M04', 'push', a.Pusher ? 1 : 0, 3.5);

    if (activa('M04')) {
        x.t += DT;
        switch (x.paso) {
            case 1: if (x.t >= 1.0) {
                        x.malo = Math.random() < 0.08;      // 8% de rechazo
                        x.d.Pusher = true;                   // botella frente al pusher
                        x.paso = x.malo ? 3 : 2; x.t = 0;
                    } break;
            case 2: pulso('M04', 'Salida', 3); x.ok++;
                    x.d.Pusher = false; x.paso = 1; x.t = 0; break;
            case 3: if (E.push >= 1) {
                        pulso('M04', 'BotDescartada', 3); x.nok++;
                        x.paso = 4; x.t = 0;
                    } break;
            case 4: if (E.push <= 0) { x.d.Pusher = false; x.paso = 1; x.t = 0; } break;
        }
    }
    tickPulsos('M04');
    return Object.assign({}, a, x.d, { CNT_OK: x.ok, CNT_NOK: x.nok });
}

// ================================================================ M05
function simM05() {
    const x = S.M05, E = x.ejes;
    const a = {
        ConveyorIngreso: activa('M05') && x.paso <= 2,
        Freno:      x.paso >= 3 && x.paso <= 6,
        Barreras:   !(x.paso >= 4 && x.paso <= 6),
        Pusher:     x.paso === 5,
        Caja:       x.paso >= 7 && x.paso <= 12,
        ConveyorSalida: x.paso >= 8,
        Cuchillas:  x.paso === 9,
        BrazoCelofan: x.paso === 11
    };
    if (S.modo.M05 === 'stop') a.ConveyorIngreso = false;

    mov('M05', 'freno',   a.Freno    ? 1 : 0, 3.0);
    mov('M05', 'barrera', a.Barreras ? 1 : 0, 2.5);
    mov('M05', 'push',    a.Pusher   ? 1 : 0, 3.0);
    mov('M05', 'caja',    a.Caja     ? 1 : 0, 1.6);
    mov('M05', 'cuch',    a.Cuchillas? 1 : 0, 3.0);
    mov('M05', 'cel',     a.BrazoCelofan ? 1 : 0, 2.0);

    const s = {
        FrenoArriba: E.freno <= 0, FrenoAbajo: E.freno >= 1,
        BarreraRecogida: E.barrera >= 1, BarreraExtendida: E.barrera <= 0,
        CajaAbajo: E.caja <= 0, CajaArriba: E.caja >= 1,
        CuchillasAbiertas: E.cuch <= 0, CuchillasCerradas: E.cuch >= 1,
        BrazoCelofanRecogido: E.cel <= 0, BrazoCelofanExtendido: E.cel >= 1,
        PusherRecogido: E.push <= 0
    };

    if (activa('M05')) {
        x.t += DT;
        switch (x.paso) {
            case 1: if (x.t >= 0.7) { pulso('M05', 'EntradaBotelllas', 2); x.bot++; x.t = 0;
                                      if (x.bot >= 4) x.paso = 2; } break;
            case 2: x.d['4BotellaAlineada'] = true; x.paso = 3; x.t = 0; break;
            case 3: if (s.FrenoAbajo) { x.paso = 4; x.t = 0; } break;
            case 4: if (s.BarreraExtendida) { x.paso = 5; x.t = 0; } break;
            case 5: if (E.push >= 1) { x.fila++; x.d['Fila' + Math.min(x.fila, 3)] = true;
                                       x.paso = 6; x.t = 0; } break;
            case 6: if (s.PusherRecogido) {
                        x.bot = 0; x.d['4BotellaAlineada'] = false;
                        if (x.fila >= 3) { x.paso = 7; } else { x.paso = 1; }
                        x.t = 0;
                    } break;
            case 7: if (s.CajaArriba) { pulso('M05', 'SalidaPackApilado', 3); x.paso = 8; x.t = 0; } break;
            case 8: if (x.t >= 0.8) { pulso('M05', 'IngresoCuchillas', 3); x.paso = 9; x.t = 0; } break;
            case 9: if (s.CuchillasCerradas) { x.paso = 10; x.t = 0; } break;
            case 10: if (s.CuchillasAbiertas) { pulso('M05', 'PosCuchillas', 3); x.paso = 11; x.t = 0; } break;
            case 11: if (s.BrazoCelofanExtendido) { x.paso = 12; x.t = 0; } break;
            case 12: if (s.BrazoCelofanRecogido) { pulso('M05', 'EntradaTunel', 3); x.paso = 13; x.t = 0; } break;
            case 13: if (x.t >= 1.5) {
                        pulso('M05', 'SalidaTunel', 3); x.ok++;
                        x.fila = 0; x.d.Fila1 = x.d.Fila2 = x.d.Fila3 = false;
                        x.paso = 1; x.t = 0;
                     } break;
        }
    }
    tickPulsos('M05');
    return Object.assign({}, a, s, x.d, { CNT_Packs: x.ok });
}

// ------------------------------------- PARADAS TEMPORALES Y RECUPERACION
// Toda anomalia (aleatoria o inyectada a mano) nace con una duracion.
// Al vencer, la maquina vuelve sola a marcha: simula que el operario ya
// atendio el problema. Con dur = 0 la anomalia es permanente hasta LIMPIAR.
//
//   PAUSA  : 20 - 60 s     (ajuste, cambio de formato, atasco menor)
//   PARO   : 40 - 120 s    (intervencion de mantenimiento)
//   FALLO  : lo que diga el inject
for (const m of IDS) {

    // a) cuenta atras de la anomalia en curso
    if (S.tRec[m] > 0) {
        S.tRec[m] -= DT;
        if (S.tRec[m] <= 0) {
            S.tRec[m]  = 0;
            S.modo[m]  = 'run';
            S.fallo[m] = false;
        }
        continue;                      // mientras dure, no se generan nuevas
    }

    // b) anomalias aleatorias, solo si la maquina esta sana
    if (S.demo && S.modo[m] === 'run' && !S.fallo[m] && Math.random() < 0.0008) {
        if (Math.random() < 0.65) {
            S.modo[m] = 'pause';  S.tRec[m] = 20 + Math.random() * 40;
        } else {
            S.modo[m] = 'stop';   S.tRec[m] = 40 + Math.random() * 80;
        }
    }
}

// ---------------------------------------------------- EJECUTAR
const V = {
    M01: simM01(), M02: simM02(), M03: simM03(), M04: simM04(), M05: simM05()
};

flow.set('sim', S);

// ---------------------------------------------------- SALIDAS
const porMaquina = IDS.map(m => ({
    topic: m,
    payload: { estado: S.modo[m], paso: S[m].paso,
               restante: Math.round(S.tRec[m] || 0), valores: V[m] }
}));

// Resumen para la vista general: solo 1 vez por segundo, no 5 veces
S.tSeg += DT;
let resumen = null;
if (S.tSeg >= 1) {
    S.tSeg = 0;
    const est = {};
    IDS.forEach(m => { est[m] = { estado: S.modo[m] }; });
    resumen = { topic: 'estados', payload: est };
}

return [porMaquina, resumen];

// ===========================================================================
//  OPERARIO SIMULADO  —  reconoce las alarmas como lo haria una persona
//
//  Recibe la lista de alarmas del motor ISA-18.2 y, pasado un tiempo que
//  depende de la PRIORIDAD, envia el reconocimiento de vuelta al motor.
//  Es lo que cierra el ciclo: sin esto las alarmas quedarian activas para
//  siempre y el diario nunca mostraria un ciclo completo.
//
//  Tiempos de respuesta (segundos), con algo de azar para que no sea robotico:
//     P1  8 - 20    critica, se atiende de inmediato
//     P2  25 - 50   importante, se atiende pronto
//     P3  50 - 100  aviso, se atiende cuando se puede
//
//  Tambien reconoce las RTNUN (se normalizaron solas sin que nadie las viera),
//  que es justo lo que un operario hace al revisar la pantalla.
//
//  Para desactivarlo y reconocer a mano durante una demostracion:
//     inject  ->  { operario: false }
// ===========================================================================

if (msg.topic !== 'alarmas') return null;
if (flow.get('op_off')) return null;

const TIEMPOS = { 1: [8, 20], 2: [25, 50], 3: [50, 100] };

const lista = (msg.payload && msg.payload.lista) || [];
const ahora = Date.now() / 1000;

let O = flow.get('op') || { plan: {}, hecho: {} };
const salidas = [];
const vivas = {};

for (const a of lista) {
    // La clave incluye el estado: si la alarma cambia de UNACK a RTNUN
    // se le asigna un tiempo de atencion nuevo.
    const k = a.id + '|' + a.estado;
    vivas[k] = true;

    if (a.estado === 'ACKED') continue;      // ya atendida, se espera que se despeje
    if (O.hecho[k]) continue;                // ya se envio el reconocimiento

    if (!O.plan[k]) {                        // primera vez que se ve: se agenda
        const r = TIEMPOS[a.prio] || TIEMPOS[3];
        O.plan[k] = ahora + r[0] + Math.random() * (r[1] - r[0]);
        continue;
    }

    if (ahora >= O.plan[k]) {                // le toco el turno
        O.hecho[k] = true;
        salidas.push({ topic: 'ack', payload: { id: a.id } });
    }
}

// Se olvidan las alarmas que ya no existen, para no acumular memoria
for (const k of Object.keys(O.plan)) {
    if (!vivas[k]) { delete O.plan[k]; delete O.hecho[k]; }
}

flow.set('op', O);
return salidas.length ? [salidas] : null;

// ===========================================================================
//  CONSOLIDADOR DE LA VISTA GENERAL (L1)
//
//  Junta dos fuentes en una sola imagen de planta:
//    topic 'estados'  <- simulador (o el PLC, el dia de manana)
//    topic 'alarmas'  <- motor de alarmas ISA-18.2
//
//  SALIDA 1 -> vista general:  { M01:{estado,alarma}, ... }
//  SALIDA 2 -> 5 mensajes con las alarmas de cada maquina, para que el
//              panel ALARMAS de cada pantalla L2 se llene.
// ===========================================================================

const IDS = ['M01', 'M02', 'M03', 'M04', 'M05'];

let C = flow.get('l1') || { estados: {}, alarmas: [] };

if (msg.topic === 'estados' && msg.payload) C.estados = msg.payload;
if (msg.topic === 'alarmas' && msg.payload) C.alarmas = msg.payload.lista || [];

flow.set('l1', C);

// --- Vista general: estado + prioridad de la alarma mas grave de cada maquina
const vista = {};
IDS.forEach(m => {
    const s = C.estados[m] || {};
    const deLaMaquina = C.alarmas.filter(a => a.maq === m);
    const prio = deLaMaquina.length
        ? Math.min.apply(null, deLaMaquina.map(a => a.prio))
        : 0;
    vista[m] = { estado: s.estado || 'stop', alarma: prio };
});

// --- Alarmas repartidas por maquina, hacia cada pantalla L2
const porMaquina = IDS.map(m => ({
    topic: m,
    payload: {
        alarmas: C.alarmas
            .filter(a => a.maq === m)
            .map(a => ({ id: a.id, prio: a.prio, hora: a.ts, desc: a.desc,
                         ack: a.estado !== 'UNACK' }))
    }
}));

return [{ payload: vista }, porMaquina];

// Traduce el resultado a un texto que se lee de un vistazo
const r = msg.payload || [];
if (!r.length) { msg.payload = 'La consulta no devolvio nada.'; return msg; }

if (r[0].name !== undefined) {
    const t = r.map(x => x.name);
    const faltan = ['alarmas','historico','eventos'].filter(x => !t.includes(x));
    msg.payload = 'TABLAS EN LA BASE: ' + t.join(', ') +
        (faltan.length ? '   |   FALTAN: ' + faltan.join(', ') +
         '  -> pulsa los inject "crear tabla"' : '   |   estan las tres, correcto');
    return msg;
}

msg.payload = r.map(x =>
    `${String(x.tabla).padEnd(11)} ${String(x.filas).padStart(7)} filas   ultimo: ${x.ultimo || '-'}`
).join('\n');
return msg;

const r = msg.payload || [];
if (!r.length) { msg.payload = 'Sentencia ejecutada (sin filas de respuesta). Normal en un CREATE TABLE.'; return msg; }
if (r[0].name !== undefined) {
    const t = r.map(x => x.name);
    const faltan = ['alarmas','historico','eventos'].filter(x => !t.includes(x));
    msg.payload = 'TABLAS: ' + t.join(', ') + (faltan.length
        ? '   >>> FALTAN: ' + faltan.join(', ') + '  (pulsa el boton 1)'
        : '   >>> estan las tres, correcto');
    return msg;
}
msg.payload = r.map(x => `${String(x.tabla).padEnd(11)} ${String(x.filas).padStart(7)} filas   ultimo: ${x.ultimo || '-'}`).join('\n');
return msg;

// Idempotente: si la tabla ya existe no hace nada.
return [[
 {topic:"CREATE TABLE IF NOT EXISTS alarmas ( id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, maquina TEXT NOT NULL, alarma_id TEXT NOT NULL, prioridad INTEGER NOT NULL, descripcion TEXT NOT NULL, evento TEXT NOT NULL );"},
 {topic:"CREATE TABLE IF NOT EXISTS historico ( id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, maquina TEXT NOT NULL, estado TEXT NOT NULL, producidas INTEGER DEFAULT 0, rechazadas INTEGER DEFAULT 0, seg_run INTEGER DEFAULT 0, seg_pause INTEGER DEFAULT 0, seg_stop INTEGER DEFAULT 0 );"},
 {topic:"CREATE TABLE IF NOT EXISTS eventos ( id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, tipo TEXT NOT NULL, maquina TEXT, detalle TEXT NOT NULL );"}
]];
